import { app, type BrowserWindow } from 'electron'
import { join } from 'node:path'

type Runtime = {
  DynWinRtType: {
    enumType: (
      name: string,
      names: string[],
      values: unknown[]
    ) => { iid: () => { toString: () => string } }
    iAsyncOperation: (type: unknown) => { iid: () => { toString: () => string } }
  }
  DynWinRtValue: { activationFactory: (name: string) => { release: () => void } }
}

function loadBindings() {
  // Generated by scripts/generate-windows-hello.ps1 on Windows.
  const root = join(app.getAppPath(), 'windows-generated')
  const runtime = require('@microsoft/dynwinrt') as Runtime
  const { DynCom } = require('@microsoft/dynwinrt/com/unsafe') as {
    DynCom: {
      projectWinRtAsync: (
        raw: unknown,
        type: unknown
      ) => { toPromise: () => Promise<{ toNumber: () => number }>; release: () => void }
    }
  }
  const generated = require(join(root, 'index.js')) as {
    UserConsentVerifier: { checkAvailabilityAsync: () => Promise<number> }
    UserConsentVerifierAvailability: Record<string, number>
    UserConsentVerificationResult: Record<string, number>
  }
  const { IUserConsentVerifierInterop } = require(
    join(root, 'com/windows/win32/system/win-rt/IUserConsentVerifierInterop.js')
  ) as {
    IUserConsentVerifierInterop: {
      _fromNative: (value: unknown) => {
        requestVerificationForWindowAsync: (
          handle: Buffer,
          reason: string,
          iid: string
        ) => { release: () => void }
        release: () => void
      }
    }
  }
  return { runtime, DynCom, generated, IUserConsentVerifierInterop }
}

export async function isWindowsHelloAvailable(): Promise<boolean> {
  if (process.platform !== 'win32') return false
  try {
    const { generated } = loadBindings()
    return (
      (await generated.UserConsentVerifier.checkAvailabilityAsync()) ===
      generated.UserConsentVerifierAvailability.Available
    )
  } catch {
    return false
  }
}

export async function verifyWindowsHello(window: BrowserWindow): Promise<boolean> {
  if (process.platform !== 'win32') return false
  try {
    const { runtime, DynCom, generated, IUserConsentVerifierInterop } = loadBindings()
    const resultType = runtime.DynWinRtType.enumType(
      'Windows.Security.Credentials.UI.UserConsentVerificationResult',
      Object.keys(generated.UserConsentVerificationResult),
      Object.values(generated.UserConsentVerificationResult)
    )
    const asyncType = runtime.DynWinRtType.iAsyncOperation(resultType)
    const factory = runtime.DynWinRtValue.activationFactory(
      'Windows.Security.Credentials.UI.UserConsentVerifier'
    )
    const interop = IUserConsentVerifierInterop._fromNative(factory)
    factory.release()
    let raw: { release: () => void } | undefined
    let operation:
      { toPromise: () => Promise<{ toNumber: () => number }>; release: () => void } | undefined
    try {
      window.show()
      window.focus()
      raw = interop.requestVerificationForWindowAsync(
        window.getNativeWindowHandle(),
        '验证身份以解锁速存',
        asyncType.iid().toString()
      )
      operation = DynCom.projectWinRtAsync(raw, asyncType)
      const result = await operation.toPromise()
      return result.toNumber() === generated.UserConsentVerificationResult.Verified
    } finally {
      operation?.release()
      raw?.release()
      interop.release()
    }
  } catch {
    return false
  }
}
